INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25101, 'John 5:18', 'John', 5, 18, '&nbsp;په دې وجه يهوديان نور هم د هغۀ په مرګ پسې شول ځکه چې يواځې دا نه چې هغۀ د سبت حُکم ماتولو بلکې هغۀ خُدائ پاک ته خپل پلار وئيلو او خپل ځان يې د خُدائ پاک سره برابر ګڼلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25102, 'John 5:19', 'John', 5, 19, '&nbsp;عيسىٰ هغوئ ته دا وفرمائيل چې، ”زۀ تاسو ته رښتيا وايم، زوئ په خپله هيڅ نۀ شى کولے بې له هغه کار نه چې خپل پلار يې په کولو ليدلے وې. ځکه څۀ چې پلار کوى هم هغه شان يې زوئ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25103, 'John 5:20', 'John', 5, 20, '&nbsp;ځکه چې پلار د زوئ سره مينه کوى او خپل ټول کارونه ورته څرګندوى. او د دې نه زيات لوئ کارونه به هغه ورته څرګند کړى نو تاسو به ورته حېران شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25104, 'John 5:21', 'John', 5, 21, '&nbsp;لکه څنګه چې پلار مړى پاڅوى او هغوئ له ژوند ورکوى دغه شان زوئ هم هر هغه چا له چې غواړى ژوند ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25105, 'John 5:22', 'John', 5, 22, '&nbsp;بيا دا چې پلار د هيچا عدالت هم نۀ کوى بلکې دا ټول اختيار يې زوئ ته سپارلے دے', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25106, 'John 5:23', 'John', 5, 23, '&nbsp;نو چې ټول د زوئ داسې عزت کوى لکه څنګه چې هغوئ د پلار عزت کوى. څوک چې د زوئ عزت نۀ کوى هغه د هغه پلار عزت نۀ کوى چا چې هغه رالېږلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25107, 'John 5:24', 'John', 5, 24, '&nbsp;زۀ تاسو ته رښتيا وايم، هر څوک چې زما خبرو ته غوږ ږدى او په هغه چا ايمان راوړى چې زۀ يې رالېږلے يم، هغه تل عُمرى ژوندون لرى. او هغه به مجرم نۀ شى ځکه چې هغه د مرګ نه ژوندون ته اوړېدلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25108, 'John 5:25', 'John', 5, 25, '&nbsp;زۀ تاسو ته رښتيا وايم، يو وخت داسې راروان دے بلکې راغلے دے چې مړى به د خُدائ پاک د زوئ آواز اورى او چې څوک يې واورى هغه به راژوندى شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25109, 'John 5:26', 'John', 5, 26, '&nbsp;ځکه څنګه چې پلار په خپله د ژوندون سرچينه دے هم دغه شان هغۀ خپل زوئ له د ژوندون ورکولو اختيار ورکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25110, 'John 5:27', 'John', 5, 27, '&nbsp;او هغۀ عيسىٰ ته د عدالت اختيار ورکړو ځکه چې هغه اِبن آدم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25111, 'John 5:28', 'John', 5, 28, '&nbsp;په دې مۀ حېرانېږئ ځکه چې داسې وخت راروان دے کله چې هغه ټول څوک چې په قبرونو کښې دى، هغه به د دۀ آواز واورى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25112, 'John 5:29', 'John', 5, 29, '&nbsp;او بهر به راوځى. چا چې نېکى کړى وى هغوئ به د تل ژوندون دپاره راپورته شى او چا چې بد کړى وى هغوئ به د عدالت دپاره راپورته کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25113, 'John 5:30', 'John', 5, 30, '&nbsp;زۀ په خپله هيڅ نۀ شم کولے. څنګه چې خُدائ پاک ما ته فرمائى زۀ هم هغسې فېصله کوم او زما فېصله درسته وى ځکه چې زۀ خپله مرضى نه بلکې د هغه چا مرضى پوره کوم چا چې زۀ رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25114, 'John 5:31', 'John', 5, 31, '&nbsp;کۀ چرې زۀ د خپل ځان په حقله ګواهى وکړم نو زما ګواهى رښتينې نۀ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25115, 'John 5:32', 'John', 5, 32, '&nbsp;بلکې يو بل څوک هم شته چې هغه زما دپاره ګواهى ورکوى او ما ته پته ده چې د هغۀ ګواهى زما په حقله رښتينې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25116, 'John 5:33', 'John', 5, 33, '&nbsp;تاسو يحيىٰ ته خپل پېغام وړُونکى ورلېږل او هغۀ هم د دې حقيقت ګواهى ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25117, 'John 5:34', 'John', 5, 34, '&nbsp;خو زۀ د انسان د ګواهۍ محتاج نۀ يم خو زۀ دا دې دپاره وايم چې تاسو بچ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25118, 'John 5:35', 'John', 5, 35, '&nbsp;يحيىٰ بلېدونکې ډيوه وه چې رڼا يې کوله او تاسو غوښتل چې د لږ وخت دپاره د هغۀ په رڼا کښې خوشحالى وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25119, 'John 5:36', 'John', 5, 36, '&nbsp;خو زۀ د يحيىٰ د ګواهۍ نه لويه ګواهى لرم. هغه کارونه چې زما پلار ما ته حواله کړى وُو چې زۀ يې سر ته ورسوم، يعنې هم هغه کارونه چې زۀ يې کوم، دا زما ګواهى ورکوى چې پلار زۀ رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25120, 'John 5:37', 'John', 5, 37, '&nbsp;او پلار چې زۀ يې رالېږلے يم هغۀ په خپله زما په حقله ګواهى ورکړې ده. تاسو هيڅکله د هغۀ آواز نۀ دے اورېدلے او نۀ مو د هغۀ صورت ليدلے دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25121, 'John 5:38', 'John', 5, 38, '&nbsp;او نۀ ستاسو په زړۀ کښې د هغۀ د کلام دپاره ځائ شته ځکه چې تاسو په هغۀ باور نۀ کوئ چا چې هغه رالېږلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25122, 'John 5:39', 'John', 5, 39, '&nbsp;تاسو په غور صحيفې لټوئ ځکه چې تاسو سوچ کوئ چې په دې کښې به ستاسو د تل ژوندون وى خو دا صحيفې هم زما په حقله ګواهى ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25123, 'John 5:40', 'John', 5, 40, '&nbsp;خو بيا هم تاسو د دې نه اِنکار کوئ چې زما طرف ته راشئ چې د تل ژوندون ومومئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25124, 'John 5:41', 'John', 5, 41, '&nbsp;زۀ د انسان نه د عزت طمع نۀ کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25125, 'John 5:42', 'John', 5, 42, '&nbsp;خو زۀ تاسو پېژنم چې ستاسو په زړُونو کښې د خُدائ پاک مينه نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25126, 'John 5:43', 'John', 5, 43, '&nbsp;زۀ د خپل پلار په نوم راغلے يم او تاسو ما نۀ قبلوئ خو کۀ بل څوک په خپله نامه راشى نو تاسو به يې قبول کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25127, 'John 5:44', 'John', 5, 44, '&nbsp;تاسو څنګه د ايمان خاوندان کېدے شئ کله چې تاسو د يو بل نه د عزت اُميد کوئ او د هغه عزت لټون نۀ کوئ کوم چې د واحد خُدائ پاک له طرفه دے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25128, 'John 5:45', 'John', 5, 45, '&nbsp;دا سوچ مۀ کوئ چې زۀ به د پلار په وړاندې په تاسو اِلزام ولګوم. په تاسو اِلزام لګونکے موسىٰ دے، په چا چې تاسو اُميد ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25129, 'John 5:46', 'John', 5, 46, '&nbsp;کۀ چرې تاسو په موسىٰ ايمان ساتئ نو په ما به يې هم ساتئ ځکه چې هغۀ زما په حقله ليکلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25130, 'John 5:47', 'John', 5, 47, '&nbsp;خو کۀ تاسو د موسىٰ په کلام ايمان نۀ ساتئ نو زۀ چې څۀ وايم تاسو به په هغې څۀ ايمان وساتئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25131, 'John 6:1', 'John', 6, 1, '&nbsp;د دې نه پس عيسىٰ د ګليل د درياب بلې غاړې ته لاړو چې ورته د تبرياس درياب هم وئيلے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25132, 'John 6:2', 'John', 6, 2, '&nbsp;او يوه لويه ګڼه ورپسې وه ځکه چې هغوئ هغه معجزې ليدلې وې چې هغۀ د بيمارانو د شفا دپاره کولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25133, 'John 6:3', 'John', 6, 3, '&nbsp;بيا عيسىٰ غرۀ ته پاس وختلو او هلته د خپلو مريدانو سره کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25134, 'John 6:4', 'John', 6, 4, '&nbsp;نو د فسح اختر چې د يهوديانو لوئ اختر دے رانزدې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25135, 'John 6:5', 'John', 6, 5, '&nbsp;بيا چې عيسىٰ خپلې سترګې اوچتې کړې نو يوه لويه ګڼه يې وليدله چې د هغۀ په طرف راروانه وه. نو عيسىٰ فيليپوس ته وفرمائيل چې، ”مونږ به د دې خلقو دپاره روټۍ د کوم ځائ نه اخلو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25136, 'John 6:6', 'John', 6, 6, '&nbsp;هغۀ دا سوال د هغۀ د آزمېښت دپاره وکړو، ځکه چې هغۀ ته په خپله دا معلومه وه چې هغه به څۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25137, 'John 6:7', 'John', 6, 7, '&nbsp;فيليپوس ورته جواب ورکړو چې، ”د دوو سوو دينارو روټۍ به هم کافى نۀ وى چې د دې خلقو لږه لږه ورسى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25138, 'John 6:8', 'John', 6, 8, '&nbsp;د هغۀ په مريدانو کښې اندرياس چې د شمعون پطروس ورور وو، هغۀ ته ووئيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25139, 'John 6:9', 'John', 6, 9, '&nbsp;”دلته يو هلک دے چې ورسره د اوربشو پينځۀ روټۍ او دوه کبان شته، خو دا د دې دومره ډېرو خلقو دپاره هيڅ هم نۀ دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25140, 'John 6:10', 'John', 6, 10, '&nbsp;عيسىٰ وفرمائيل، ”دا خلق کښېنوئ.“ هلته په هغه ځائ کښې ښۀ ډېر واښۀ وُو، نو هغوئ لاندې په زمکه کښېناستل او ټول تقريباً پينځۀ زره سړى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25141, 'John 6:11', 'John', 6, 11, '&nbsp;بيا عيسىٰ روټۍ واخستلې، شُکر يې پرې وکړو او هغه يې په هغه ناستو خلقو تقسيم کړې. او هم دغسې يې د کبانو سره وکړل او هغوئ چې څومره غوښتل نو دومره يې ورکړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25142, 'John 6:12', 'John', 6, 12, '&nbsp;کله چې ټول ښۀ ماړۀ شول نو هغۀ خپلو مريدانو ته وفرمائيل، ”دا پاتې شوې ټوکړې راټولې کړئ نو چې هيڅ هم درنه ضائع نۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25143, 'John 6:13', 'John', 6, 13, '&nbsp;نو هغوئ هغه راټولې کړې او د اوربشو د پينځو روټو د هغه پاتې شوو ټوکړو نه کومې چې خلقو خوړلې وې دولس ټوکرۍ ډکې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25144, 'John 6:14', 'John', 6, 14, '&nbsp;کله چې خلقو دا معجزه وليدله چې عيسىٰ وکړه هغوئ يو بل ته ووئيل، ”يقيناً دا هغه پېغمبر دے کوم چې دُنيا ته راتلونکے وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25145, 'John 6:15', 'John', 6, 15, '&nbsp;کله چې عيسىٰ د هغوې په نيت پوهه شو چې هغوئ هغه خپل بادشاه جوړول غواړى نو هغه په خپله غرۀ ته واپس لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25146, 'John 6:16', 'John', 6, 16, '&nbsp;کله چې ماښام شو نو د عيسىٰ مريدان ښکته د درياب غاړې ته لاړل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25147, 'John 6:17', 'John', 6, 17, '&nbsp;په کِشتۍ کښې کښېناستل او د سيند پورې غاړې کفرنحُوم ته روان شول. نو تيارۀ شوې وه او عيسىٰ لا هغوئ سره مِلاو شوے نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25148, 'John 6:18', 'John', 6, 18, '&nbsp;په دې دوران کښې د درياب اوبۀ په اوچتېدو شوې ځکه چې تېز طوفان راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25149, 'John 6:19', 'John', 6, 19, '&nbsp;کله چې هغوئ درې څلور ميله کِشتۍ وچلوله نو هغوئ عيسىٰ د اوبو دپاسه روان وليدو چې د کِشتۍ طرف ته رانزدې کېدو. او هغوئ يرې واخستل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25150, 'John 6:20', 'John', 6, 20, '&nbsp;خو عيسىٰ هغوئ ته وفرمائيل، ”مۀ يرېږئ، دا زۀ يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25151, 'John 6:21', 'John', 6, 21, '&nbsp;نو بيا هغوئ دا غوښتل چې عيسىٰ کِشتۍ ته راوخېژى او سمدستى کِشتۍ هغه غاړې ته ورسېدله چرته چې دوئ روان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25152, 'John 6:22', 'John', 6, 22, '&nbsp;بل سحر هغه ګڼ خلق چې د درياب په بله غاړه ايسار شوى وُو هغوئ وليدل چې هلته صرف يوه کِشتۍ وه او د دې نه هم خبر شول چې عيسىٰ د خپلو مريدانو سره کِشتۍ ته نۀ وو ختلے، بلکې د هغۀ مريدان د هغۀ نه بغېر تلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25153, 'John 6:23', 'John', 6, 23, '&nbsp;بيا د تبرياس نه نورې کِشتۍ دېخوا راغلې چرته چې خلقو د مالِک د شُکر ويستلو نه وروستو روټۍ خوړلې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25154, 'John 6:24', 'John', 6, 24, '&nbsp;کله چې خلقو وکتل چې نۀ خو عيسىٰ او نۀ يې مريدان هلته شته نو هغوئ په کشتو کښې سوارۀ شول او د عيسىٰ په تلاش کښې پورې غاړه کفرنحُوم ته لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25155, 'John 6:25', 'John', 6, 25, '&nbsp;کله چې هغوئ هغه د درياب په بله غاړه وموندو هغوئ عيسىٰ ته ووئيل، ”اُستاذه، تۀ کله دلته راغلې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25156, 'John 6:26', 'John', 6, 26, '&nbsp;عيسىٰ جواب ورکړو، ”زۀ تاسو ته رښتيا وايم چې تاسو زما تلاش په دې وجه نۀ کوئ چې تاسو نښې وکتلې بلکې ځکه چې تاسو روټۍ وخوړله او لوږه مو ختمه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25157, 'John 6:27', 'John', 6, 27, '&nbsp;د داسې خوراک دپاره خوارى مۀ کوئ چې ختميږى بلکې د هغې روټۍ دپاره خوارى کوئ چې تر ابده پاتې کيږى، او کوم به چې اِبن آدم تاسو له درکړى. ځکه چې هم په هغۀ باندې خُدائ پلار خپل مُهر لګولے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25158, 'John 6:28', 'John', 6, 28, '&nbsp;بيا هغوئ هغۀ ته ووئيل چې، ”مونږ له څۀ کول په کار دى چې د خُدائ پاک د رضا کارونه وکړُو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25159, 'John 6:29', 'John', 6, 29, '&nbsp;عيسىٰ جواب ورکړو چې، ”د خُدائ پاک د رضا کار دا دے چې په هغه چا ايمان راوړئ چې هغۀ رالېږلے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25160, 'John 6:30', 'John', 6, 30, '&nbsp;نو هغوئ هغۀ ته ووئيل، ”نو تۀ مونږ ته کومه معجزه ښکاره کوې چې مونږ يې ووينو او په تا ايمان راوړو؟ تۀ څۀ کار کولے شې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25161, 'John 6:31', 'John', 6, 31, '&nbsp;لکه چې زمونږ پلار نيکۀ په صحرا کښې من وخوړل، صحيفې فرمائى چې، موسىٰ هم هغوئ له د آسمان نه من ورکړل چې وې خورى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25162, 'John 6:32', 'John', 6, 32, '&nbsp;بيا عيسىٰ جواب ورکړو، ”زۀ تاسو ته رښتيا وايم چې دا موسىٰ نۀ وو چې تاسو له يې د آسمان نه من درکړل بلکې دا زما پلار دے چې تاسو له د آسمان نه حقيقى روټۍ درکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25163, 'John 6:33', 'John', 6, 33, '&nbsp;ځکه چې د خُدائ پاک روټۍ هغه ده چې د آسمان نه راکوزيږى او دُنيا ته ژوندون ورکوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25164, 'John 6:34', 'John', 6, 34, '&nbsp;نو هغوئ هغۀ ته ووئيل، ”مالِکه، مونږ ته دغه روټۍ همېشه راکوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25165, 'John 6:35', 'John', 6, 35, '&nbsp;عيسىٰ هغوئ ته وفرمائيل، ”زۀ د ژوندون روټۍ يم. څوک چې ما له راځى هغه به هيڅکله نۀ اوږى کيږى او څوک چې په ما ايمان راوړى هغه به هيڅکله نۀ تږى کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25166, 'John 6:36', 'John', 6, 36, '&nbsp;خو ما تاسو ته وفرمائيل چې تاسو زۀ ليدلے يم او بيا هم په ما ايمان نۀ راوړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25167, 'John 6:37', 'John', 6, 37, '&nbsp;هر څوک چې پلار ما ته حواله کړى هغه به ما له راشى او څوک چې ما له راشى هغه به زۀ هيڅکله ونۀ شړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25168, 'John 6:38', 'John', 6, 38, '&nbsp;ځکه چې زۀ د آسمان نه د خپلې رضا پوره کولو دپاره نۀ يم راکوز شوے بلکې د هغۀ د رضا پوره کولو دپاره چا چې زۀ رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25169, 'John 6:39', 'John', 6, 39, '&nbsp;او دا د هغۀ رضا ده چا چې زۀ رالېږلے يم چې زۀ هغه ټولو نه يو هم ورک نۀ کړم څۀ چې هغۀ ما له راکړى دى بلکې د قيامت په ورځ يې راپاڅوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25170, 'John 6:40', 'John', 6, 40, '&nbsp;ځکه چې دا زما د پلار مرضى ده چې هر څوک چې زوئ ووينى او په هغۀ ايمان راوړى، هغه به د ابدى ژوندون خاوند شى، او زۀ به هغوئ د قيامت په ورځ بيا راپاڅوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25171, 'John 6:41', 'John', 6, 41, '&nbsp;په دې يهوديان د هغۀ په حقله وغورېدل ځکه چې هغۀ وفرمائيل چې، ”زۀ هغه روټۍ يم چې د آسمان نه راکوزه شوې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25172, 'John 6:42', 'John', 6, 42, '&nbsp;هغوئ ووئيل، ”ولې دا عيسىٰ د يوسف زوئ نۀ دے چې مونږ يې مور او پلار پېژنو، نو بيا څنګه هغه وائى چې زۀ د آسمان نه راکوز شوے يم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25173, 'John 6:43', 'John', 6, 43, '&nbsp;نو عيسىٰ جواب ورکړو چې، ”په خپلو کښې مۀ غورېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25174, 'John 6:44', 'John', 6, 44, '&nbsp;څوک هم ما له تر هغې نۀ شى راتلے ترڅو چې هغه پلار چې زۀ يې رالېږلے يم هغه يې ما ته راونۀ لېږى، او زۀ به هغه د قيامت په ورځ راپاڅوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25175, 'John 6:45', 'John', 6, 45, '&nbsp;دا د نبيانو په صحيفو کښې ليکلے شوى دى چې هغوئ ټولو ته به خُدائ پاک تعليم ورکړى. هر هغه څوک چې د پلار اورى او د هغۀ نه زده کوى هغه ما له راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25176, 'John 6:46', 'John', 6, 46, '&nbsp;هيچا پلار نۀ دے ليدلے بغېر د هغۀ نه چې د خُدائ پاک د طرفه دے، صرف هغۀ پلار ليدلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25177, 'John 6:47', 'John', 6, 47, '&nbsp;زۀ تاسو ته رښتيا وايم څوک چې ايمان راوړى هغه د تل ژوندون خاوند دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25178, 'John 6:48', 'John', 6, 48, '&nbsp;زۀ د ژوندون روټۍ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25179, 'John 6:49', 'John', 6, 49, '&nbsp;ستاسو پلار نيکونو په صحرا کښې من وخوړل خو هغوئ مړۀ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25180, 'John 6:50', 'John', 6, 50, '&nbsp;دا هغه روټۍ ده چې د آسمان نه راغلې ده، نو چې څوک دا روټۍ وخورى هغه به نۀ مرى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25181, 'John 6:51', 'John', 6, 51, '&nbsp;زۀ د ژوندون روټۍ يم چې د آسمان نه راکوزه شوې ده. څوک چې دا روټۍ وخورى هغه به تل ژوندے وى. او کومه روټۍ چې زۀ د دُنيا د ژوندون دپاره ورکوم هغه زما بدن دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25182, 'John 6:52', 'John', 6, 52, '&nbsp;بيا د يهوديانو په مينځ کښې تېز بحث شروع شو، هغوئ ووئيل چې، ”دا سړے خپل بدن مونږ ته خوړلو له څنګه راکولے شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25183, 'John 6:53', 'John', 6, 53, '&nbsp;نو عيسىٰ هغوئ ته وفرمائيل، ”زۀ تاسو ته رښتيا وايم چې ترڅو چې تاسو د اِبن آدم بدن ونۀ خورئ او د هغۀ وينه ونۀ څښئ نو تاسو کښې به ابدى ژوندون نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25184, 'John 6:54', 'John', 6, 54, '&nbsp;څوک چې زما بدن وخورى او زما وينه وڅښى هغه د تل ژوندون خاوند دے او زۀ به يې د قيامت په ورځ راپاڅوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25185, 'John 6:55', 'John', 6, 55, '&nbsp;زما بدن حقيقى خوراک دے او زما وينه حقيقى څښاک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25186, 'John 6:56', 'John', 6, 56, '&nbsp;څوک چې زما غوښه خورى او زما وينه څښى هغه په ما کښې او زۀ په هغۀ کښې اوسېږم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25187, 'John 6:57', 'John', 6, 57, '&nbsp;لکه څنګه چې ژوندى پلار زۀ راولېږلم او زۀ د پلار په وجه ژوندے يم، دغه شان څوک چې زما بدن وخورى هغوئ به زما په وجه ژوندى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25188, 'John 6:58', 'John', 6, 58, '&nbsp;دا هغه روټۍ ده چې د آسمان نه راکوزه شوې ده او دا د هغه روټۍ په شان نۀ ده چې ستاسو پلار نيکونو وخوړه او مړۀ شول. خو څوک چې دا روټۍ وخورى هغه به تل تر تله ژوندى وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25189, 'John 6:59', 'John', 6, 59, '&nbsp;عيسىٰ دا خبرې هغه وخت وکړې کله چې هغۀ په کفرنحُوم کښې په عبادتخانه کښې تعليم ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25190, 'John 6:60', 'John', 6, 60, '&nbsp;کله چې د هغۀ ډېرو مريدانو دا خبرې واورېدې هغوئ ووئيل چې، ”دا تعليم سخت دے، څوک دا منلے شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25191, 'John 6:61', 'John', 6, 61, '&nbsp;خو عيسىٰ خبر وو چې د هغۀ مريدان په دې حقله غوريږى، نو هغۀ هغوئ ته وفرمائيل چې، ”ولې تاسو په دې خفه شوئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25192, 'John 6:62', 'John', 6, 62, '&nbsp;بيا به تاسو څۀ سوچ کوئ کۀ تاسو اِبن آدم هغه ځائ ته په ختو ووينئ چرته چې هغه مخکښې وو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25193, 'John 6:63', 'John', 6, 63, '&nbsp;دا د خُدائ پاک روح دے چې ژوند ورکوى، انسانى بدن بې‌فائدې دے. کومې خبرې چې ما تاسو ته کړې دى هغه روح او ژوند دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25194, 'John 6:64', 'John', 6, 64, '&nbsp;خو په تاسو کښې ځينې داسې دى چې ايمان نۀ راوړى.“ ځکه چې عيسىٰ ته د اول نه دا پته وه چې څوک به ايمان نۀ راوړى او څوک به په هغۀ مُخبرى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25195, 'John 6:65', 'John', 6, 65, '&nbsp;بيا هغۀ وفرمائيل چې، ”دغه وجه ده چې ما تاسو ته وفرمائيل چې، هيڅوک هم ما ته نۀ شى راتلے ترڅو چې پلار ورته دا توفيق ورنۀ کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25196, 'John 6:66', 'John', 6, 66, '&nbsp;په دې وجه د عيسىٰ ډېر مريدان د هغۀ نه واوړېدل او نور د هغۀ سره نۀ ګرځېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25197, 'John 6:67', 'John', 6, 67, '&nbsp;نو عيسىٰ هغه دولسو مريدانو نه تپوس وکړو، ”ولې تاسو هم ما نه تلل غواړئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25198, 'John 6:68', 'John', 6, 68, '&nbsp;شمعون پطروس ورته جواب ورکړو، ”مالِکه، چا له به مونږ لاړ شُو؟ تا سره خو د تل ژوندون خبرې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25199, 'John 6:69', 'John', 6, 69, '&nbsp;زمونږ په تا ايمان دے او زمونږ په دې ايمان دے چې تۀ د خُدائ پاک قُدوس يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25200, 'John 6:70', 'John', 6, 70, '&nbsp;عيسىٰ هغوئ ته جواب ورکړو، ”ولې ما تاسو دولس واړه غوره کړى نۀ يئ څۀ؟ خو په تاسو کښې يو کس شېطان دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');